"use client";

import { useEffect, useState } from "react";

type Message = {
  role: "user" | "ai";
  text: string;
};

type Chat = {
  id: string;
  title: string;
  messages: Message[];
};

const STARTER_MESSAGE: Message = {
  role: "ai",
  text: "Hello 👋 I'm Vision AI.\n\nI can help you create, research, code, write, analyze, and build almost anything.",
};

export default function Dashboard() {
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);

  const [chats, setChats] = useState<Chat[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);

  // Load chats from browser storage
  useEffect(() => {
    const savedChats = localStorage.getItem("vision-ai-chats");

    if (savedChats) {
      try {
        const parsedChats: Chat[] = JSON.parse(savedChats);

        if (parsedChats.length > 0) {
          setChats(parsedChats);
          setCurrentChatId(parsedChats[0].id);
          return;
        }
      } catch (error) {
        console.error("Could not load saved chats:", error);
      }
    }

    createNewChat();
  }, []);

  // Save chats
  useEffect(() => {
    if (chats.length > 0) {
      localStorage.setItem("vision-ai-chats", JSON.stringify(chats));
    }
  }, [chats]);

  const currentChat = chats.find(
    (chat) => chat.id === currentChatId
  );

  function createNewChat() {
    const newChat: Chat = {
      id: Date.now().toString(),
      title: "New Chat",
      messages: [STARTER_MESSAGE],
    };

    setChats((prev) => [newChat, ...prev]);
    setCurrentChatId(newChat.id);
    setInput("");
  }

  function openChat(id: string) {
    setCurrentChatId(id);
    setInput("");
  }

  async function sendMessage() {
    if (!input.trim() || loading || !currentChatId) return;

    const userText = input.trim();

    const userMessage: Message = {
      role: "user",
      text: userText,
    };

    // Add user message
    setChats((prev) =>
      prev.map((chat) => {
        if (chat.id !== currentChatId) return chat;

        const isFirstUserMessage = !chat.messages.some(
          (message) => message.role === "user"
        );

        return {
          ...chat,
          title: isFirstUserMessage
            ? userText.slice(0, 35) +
              (userText.length > 35 ? "..." : "")
            : chat.title,
          messages: [...chat.messages, userMessage],
        };
      })
    );

    setInput("");
    setLoading(true);

    // Add empty AI message
    setChats((prev) =>
      prev.map((chat) => {
        if (chat.id !== currentChatId) return chat;

        return {
          ...chat,
          messages: [
            ...chat.messages,
            {
              role: "ai",
              text: "",
            },
          ],
        };
      })
    );

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          message: userText,
        }),
      });

      if (!res.ok) {
        throw new Error("Failed to get response");
      }

      if (!res.body) {
        throw new Error("No response body");
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder();

      let aiText = "";

      while (true) {
        const { done, value } = await reader.read();

        if (done) break;

        const chunk = decoder.decode(value, {
          stream: true,
        });

        aiText += chunk;

        setChats((prev) =>
          prev.map((chat) => {
            if (chat.id !== currentChatId) return chat;

            const updatedMessages = [...chat.messages];

            updatedMessages[updatedMessages.length - 1] = {
              role: "ai",
              text: aiText,
            };

            return {
              ...chat,
              messages: updatedMessages,
            };
          })
        );
      }
    } catch (error) {
      console.error("Chat error:", error);

      setChats((prev) =>
        prev.map((chat) => {
          if (chat.id !== currentChatId) return chat;

          const updatedMessages = [...chat.messages];

          updatedMessages[updatedMessages.length - 1] = {
            role: "ai",
            text: "Something went wrong. Please try again.",
          };

          return {
            ...chat,
            messages: updatedMessages,
          };
        })
      );
    } finally {
      setLoading(false);
    }
  }

  function copyMessage(text: string) {
    navigator.clipboard.writeText(text);
  }

  return (
    <div className="h-screen bg-[#0b0b0b] text-white flex overflow-hidden">

      {/* ================= SIDEBAR ================= */}

      <aside className="hidden md:flex w-72 bg-[#111111] border-r border-white/10 flex-col">

        {/* BRAND */}

        <div className="p-5 pb-4">
          <div className="flex items-center gap-3">

            <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center font-bold text-xl">
              V
            </div>

            <div>
              <h1 className="font-semibold text-xl tracking-tight">
                Vision AI
              </h1>

              <p className="text-sm text-gray-500">
                Your AI workspace
              </p>
            </div>

          </div>
        </div>

        {/* NEW CHAT */}

        <div className="px-4">
          <button
            onClick={createNewChat}
            className="w-full py-3.5 rounded-xl bg-white text-black text-[16px] font-semibold hover:bg-gray-200 transition"
          >
            ＋ New Chat
          </button>
        </div>

        {/* CHAT HISTORY */}

        <div className="px-4 mt-7 flex-1 overflow-y-auto">

          <p className="text-sm text-gray-500 font-medium mb-3 px-1 tracking-wide">
            CHAT HISTORY
          </p>

          <div className="space-y-1">

            {chats.map((chat) => (
              <button
                key={chat.id}
                onClick={() => openChat(chat.id)}
                className={`w-full text-left px-3 py-3.5 rounded-xl transition truncate ${
                  chat.id === currentChatId
                    ? "bg-[#1f1f1f] text-white border border-white/10"
                    : "text-gray-400 hover:text-white hover:bg-white/5"
                }`}
              >
                <span className="text-[16px] font-medium">
                  {chat.title}
                </span>
              </button>
            ))}

          </div>

        </div>

        {/* PRO + USER */}

        <div className="p-4 space-y-3">

          {/* PRO CARD */}

          <div className="rounded-xl bg-gradient-to-r from-blue-600/20 to-purple-600/20 border border-white/10 p-4">

            <p className="font-semibold text-[17px]">
              Vision Pro
            </p>

            <p className="text-[15px] text-gray-400 mt-1">
              Unlimited AI power
            </p>

            <button className="mt-3 bg-white text-black px-5 py-2.5 rounded-lg text-[15px] font-medium hover:bg-gray-200 transition">
              Upgrade
            </button>

          </div>

          {/* USER */}

          <div className="flex items-center gap-3 p-3 rounded-xl hover:bg-white/10 cursor-pointer">

            <div className="w-10 h-10 rounded-full bg-gray-700 flex items-center justify-center text-[16px]">
              U
            </div>

            <div>

              <p className="text-[16px] font-medium">
                User
              </p>

              <p className="text-sm text-gray-500">
                Free Plan
              </p>

            </div>

          </div>

        </div>

      </aside>

      {/* ================= MAIN ================= */}

      <main className="flex-1 flex flex-col min-w-0">

        {/* HEADER */}

        <header className="h-16 border-b border-white/10 flex items-center justify-between px-6 shrink-0">

          <div>

            <h2 className="font-semibold text-[18px] tracking-tight">
              Vision AI
            </h2>

            <p className="text-sm text-gray-500">
              Your AI workspace
            </p>

          </div>

          <button className="bg-white/10 px-4 py-2.5 rounded-xl text-[15px] hover:bg-white/20 transition">
            ⚡ Pro
          </button>

        </header>

        {/* CHAT AREA */}

        <section className="flex-1 overflow-y-auto px-6 py-10">

          <div className="max-w-4xl mx-auto space-y-10">

            {currentChat?.messages.map((msg, index) => (

              <div
                key={index}
                className={`flex gap-4 ${
                  msg.role === "user"
                    ? "justify-end"
                    : "justify-start"
                }`}
              >

                {/* AI AVATAR */}

                {msg.role === "ai" && (
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center shrink-0 text-base">
                    ✨
                  </div>
                )}

                {/* MESSAGE */}

                <div
                  className={`max-w-[85%] ${
                    msg.role === "user"
                      ? "bg-[#2f2f2f] px-6 py-3.5 rounded-3xl text-[18px] leading-7"
                      : "text-gray-100 text-[20px] leading-9 tracking-[0.01em]"
                  }`}
                >

                  {msg.text}

                  {/* AI ACTIONS */}

                  {msg.role === "ai" && msg.text && (
                    <div className="mt-5 flex gap-5 text-sm text-gray-500">

                      <button className="hover:text-white transition">
                        👍
                      </button>

                      <button className="hover:text-white transition">
                        👎
                      </button>

                      <button
                        onClick={() => copyMessage(msg.text)}
                        className="hover:text-white transition"
                      >
                        Copy
                      </button>

                    </div>
                  )}

                </div>

              </div>

            ))}

            {/* LOADING */}

            {loading && (
              <div className="flex gap-3 text-gray-500 text-[16px]">

                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center">
                  ✨
                </div>

                <div className="pt-2 animate-pulse text-[16px]">
                  Thinking...
                </div>

              </div>
            )}

          </div>

        </section>

        {/* INPUT */}

        <footer className="p-6 shrink-0">

          <div className="max-w-4xl mx-auto">

            <div className="bg-[#1f1f1f] border border-white/10 rounded-3xl px-5 py-4 flex items-center gap-3 shadow-lg">

              <button className="text-gray-400 text-xl hover:text-white transition">
                ＋
              </button>

              <input
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    sendMessage();
                  }
                }}
                placeholder="Message Vision AI"
                disabled={loading}
                className="flex-1 bg-transparent outline-none text-[17px] placeholder:text-gray-500"
              />

              <button className="text-gray-400 text-xl hover:text-white transition">
                🎙
              </button>

              <button
                onClick={sendMessage}
                disabled={loading || !input.trim()}
                className="bg-white text-black w-11 h-11 rounded-xl font-bold text-lg hover:bg-gray-200 disabled:opacity-40 disabled:cursor-not-allowed transition"
              >
                ↑
              </button>

            </div>

            <p className="text-center text-sm text-gray-600 mt-3">
              Vision AI can make mistakes. Check important information.
            </p>

          </div>

        </footer>

      </main>

    </div>
  );
}